import decoy
from collections import defaultdict


def missing_balance() -> int:
    raise SystemExit('synchronous failure')


ledger = decoy.Ledger()
ledger.balances = defaultdict(missing_balance, {'a': 100})
observed = ledger.balances
caught = False
try:
    decoy.transfer(ledger, 'a', 'missing', 30)
except SystemExit:
    caught = True
except Exception:
    pass

broken = caught and ledger.balances is observed and dict(observed) == {'a': 70}
print('REPRODUCED' if broken else 'NOT REPRODUCED')

